  "INSERT OR REPLACE INTO icono_admin_dashboard_summary (summary_key, genes, with_live, overrides, drift, current_asset_missing, missing, no_live, stale_assets, legacy_assets, zero_candidates, one_candidate, two_to_five_candidates, six_plus_candidates, updated_at)\n      SELECT 'default', COALESCE(SUM(1), 0),\n        COALESCE(SUM((COALESCE(gr.current_asset_sha256, '') <> '')), 0),\n        COALESCE(SUM((COALESCE(gr.admin_override, 0) = 1 AND COALESCE(gr.current_asset_sha256, '') <> '')), 0),\n        COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0),\n        COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0),\n        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0),\n        COALESCE(SUM((COALESCE(gr.current_asset_sha256, '') = '')), 0),\n        COALESCE(SUM(COALESCE(gr.stale_count, 0)), 0),\n        COALESCE(SUM(COALESCE(gr.legacy_count, 0)), 0),\n        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0),\n        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 1)), 0),\n        COALESCE(SUM((COALESCE(gr.candidate_count, 0) BETWEEN 2 AND 5)), 0),\n        COALESCE(SUM((COALESCE(gr.candidate_count, 0) >= 6)), 0), CURRENT_TIMESTAMP\n      FROM icono_gene_catalog gc LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = gc.gene_symbol;",
  "WITH counts AS (\n    SELECT COALESCE(SUM(1), 0) AS count_all,\n      COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0) AS count_mismatch,\n      COALESCE(SUM((COALESCE(gr.admin_override, 0) = 1)), 0) AS count_pinned,\n      COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0) AS count_missing,\n      COALESCE(SUM((COALESCE(gr.stale_count, 0) > 0)), 0) AS count_stale FROM icono_admin_gene_rollup gr\n    ), filters(filter) AS (VALUES ('all'), ('mismatch'), ('pinned'), ('missing'), ('stale'))\n    INSERT OR REPLACE INTO icono_admin_gallery_count_cache (count_key, mode, filter, total, updated_at)\n    SELECT 'live:' || filter, 'live', filter, CASE filter WHEN 'all' THEN count_all WHEN 'mismatch' THEN count_mismatch WHEN 'pinned' THEN count_pinned WHEN 'missing' THEN count_missing WHEN 'stale' THEN count_stale END,\n      CURRENT_TIMESTAMP FROM counts CROSS JOIN filters;",
  "WITH counts AS (\n    SELECT COALESCE(SUM(1), 0) AS count_all,\n      COALESCE(SUM(COALESCE(gr.current_asset_missing, 0) = 1), 0) AS count_mismatch,\n      COALESCE(SUM(COALESCE(gr.admin_override, 0) = 1), 0) AS count_pinned,\n      COALESCE(SUM(0), 0) AS count_missing,\n      COALESCE(SUM(COALESCE(pa.is_stale, 0) = 1), 0) AS count_stale FROM icono_portrait_assets pa LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = pa.gene_symbol WHERE pa.asset_sha256 <> ''\n    ), filters(filter) AS (VALUES ('all'), ('mismatch'), ('pinned'), ('missing'), ('stale'))\n    INSERT OR REPLACE INTO icono_admin_gallery_count_cache (count_key, mode, filter, total, updated_at)\n    SELECT 'all:' || filter, 'all', filter, CASE filter WHEN 'all' THEN count_all WHEN 'mismatch' THEN count_mismatch WHEN 'pinned' THEN count_pinned WHEN 'missing' THEN count_missing WHEN 'stale' THEN count_stale END,\n      CURRENT_TIMESTAMP FROM counts CROSS JOIN filters;",
  "CREATE TRIGGER trg_icono_admin_counts_rollup_insert AFTER INSERT ON icono_admin_gene_rollup\nBEGIN\n  UPDATE icono_admin_dashboard_summary SET\n    with_live = with_live + ((COALESCE(NEW.current_asset_sha256, '') <> '')) - (('' <> '')),\n    overrides = overrides + ((COALESCE(NEW.admin_override, 0) = 1 AND COALESCE(NEW.current_asset_sha256, '') <> '')) - ((0 = 1 AND '' <> '')),\n    drift = drift + ((COALESCE(NEW.current_asset_missing, 0) = 1)) - ((0 = 1)),\n    current_asset_missing = current_asset_missing + ((COALESCE(NEW.current_asset_missing, 0) = 1)) - ((0 = 1)),\n    missing = missing + ((COALESCE(NEW.candidate_count, 0) = 0)) - ((0 = 0)),\n    no_live = no_live + ((COALESCE(NEW.current_asset_sha256, '') = '')) - (('' = '')),\n    stale_assets = stale_assets + (COALESCE(NEW.stale_count, 0)) - (0),\n    legacy_assets = legacy_assets + (COALESCE(NEW.legacy_count, 0)) - (0),\n    zero_candidates = zero_candidates + ((COALESCE(NEW.candidate_count, 0) = 0)) - ((0 = 0)),\n    one_candidate = one_candidate + ((COALESCE(NEW.candidate_count, 0) = 1)) - ((0 = 1)),\n    two_to_five_candidates = two_to_five_candidates + ((COALESCE(NEW.candidate_count, 0) BETWEEN 2 AND 5)) - ((0 BETWEEN 2 AND 5)),\n    six_plus_candidates = six_plus_candidates + ((COALESCE(NEW.candidate_count, 0) >= 6)) - ((0 >= 6)),\n    updated_at = CURRENT_TIMESTAMP WHERE summary_key = 'default'\n    AND EXISTS (SELECT 1 FROM icono_gene_catalog WHERE gene_symbol = NEW.gene_symbol);\n  UPDATE icono_admin_gallery_count_cache SET total = total + (1 - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:all' AND (1 - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:mismatch' AND ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.admin_override, 0) = 1) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:pinned' AND ((COALESCE(NEW.admin_override, 0) = 1) - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.candidate_count, 0) = 0) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:missing' AND ((COALESCE(NEW.candidate_count, 0) = 0) - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.stale_count, 0) > 0) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:stale' AND ((COALESCE(NEW.stale_count, 0) > 0) - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + (((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) *\n      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = NEW.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) <> 0;\n  UPDATE icono_admin_gallery_count_cache SET total = total + (((COALESCE(NEW.admin_override, 0) = 1) - 0) *\n      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = NEW.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND ((COALESCE(NEW.admin_override, 0) = 1) - 0) <> 0;\nEND;",
